-- =============================================================================
-- RedSokappy — Esquema PostgreSQL para Supabase
-- Migración del esquema Oracle "TOKANA" (Soka Gakkai del Paraguay)
-- Stack: Next.js 14 + Supabase (Postgres + Auth + RLS). Filosofía: costo-cero / open-source.
--
-- Convenciones aplicadas respecto del Oracle original:
--   * IDs con GENERATED BY DEFAULT AS IDENTITY (se eliminan los triggers max+1).
--   * TODAS las FK declaradas (incluida asistencia_d, que en Oracle no tenía ninguna).
--   * Catálogos con seeds incluidos; datos transaccionales van en el script de carga aparte.
--   * Autenticación con Supabase Auth (auth.users) + tabla public.perfiles. Se descarta el MD5.
--   * RLS activado en todas las tablas.
--   * Lógica de negocio de los triggers Oracle portada a PL/pgSQL.
-- Ejecutar en el SQL Editor de Supabase (o supabase db push).
-- (Copia en el repo del esquema original del proyecto; ya está aplicado en Supabase.)
-- =============================================================================

-- Extensiones útiles
create extension if not exists "pgcrypto";

-- =============================================================================
-- 1. CATÁLOGOS
-- =============================================================================

create table region (
  id_region   bigint generated by default as identity primary key,
  nombre      varchar(100) not null
);

create table cabildo (
  id_cabildo  bigint generated by default as identity primary key,
  id_region   bigint references region(id_region),
  nombre      varchar(100) not null
);

create table distrito (
  id_distrito bigint generated by default as identity primary key,
  id_cabildo  bigint references cabildo(id_cabildo),
  nombre      varchar(100) not null
);

create table han (
  id_han      bigint generated by default as identity primary key,
  id_distrito bigint references distrito(id_distrito),
  nombre      varchar(100) not null
);

create table estados (
  id_estado   bigint generated by default as identity primary key,
  descripcion varchar(50)
);

-- Divisiones: en Oracle era texto libre duplicado; acá se normaliza a catálogo.
create table divisiones (
  codigo      varchar(10) primary key,   -- DF, DS, DJM, DJF, DN
  descripcion varchar(60) not null
);

create table tipo_evento (
  id_tipo_evento bigint generated by default as identity primary key,
  nombre         varchar(100) not null
);

create table tipos_grupos (
  id_tipo_grupo bigint generated by default as identity primary key,
  tipo_grupo    varchar(100) not null
);

create table grupos (
  id_grupo      bigint generated by default as identity primary key,
  nombre_grupo  varchar(100) not null,
  id_tipo_grupo bigint references tipos_grupos(id_tipo_grupo)
);

create table cargo (
  id_cargo bigint generated by default as identity primary key,
  cargo    varchar(50)
);

create table rol (
  id_rol bigint generated by default as identity primary key,
  rol    varchar(50)
);

create table examenes (
  id_examen bigint generated by default as identity primary key,
  nivel     varchar(50)
);

create table tipo_suscripciones (
  id_tipo_suscripcion bigint generated by default as identity primary key,
  suscripcion         varchar(50)
);

-- =============================================================================
-- 2. MIEMBROS
-- =============================================================================

create table personas (
  id_persona          bigint generated by default as identity primary key,
  nombre              varchar(100) not null,
  telefono            varchar(20),
  correo              varchar(120),                 -- Oracle tenía 20 (muy corto); se amplía.
  division            varchar(10) references divisiones(codigo),
  id_estado           bigint references estados(id_estado),
  titular_gohonzo     smallint default 0,
  fecha_ingreso       date,
  fecha_actualizacion timestamptz default now(),
  id_han              bigint references han(id_han)
);
create index ix_personas_han     on personas(id_han);
create index ix_personas_estado  on personas(id_estado);
create index ix_personas_division on personas(division);

-- =============================================================================
-- 3. ASISTENCIA (evento + detalle)
-- =============================================================================

-- Cabecera: en el modelo real ES el "evento" (no hay tabla de eventos aparte).
create table asistencia_c (
  id_asistencia    bigint generated by default as identity primary key,
  id_tipo_evento   bigint references tipo_evento(id_tipo_evento),
  fecha_asistencia date not null,
  id_han           bigint references han(id_han)
);
create index ix_asistencia_c_fecha on asistencia_c(fecha_asistencia);
create index ix_asistencia_c_tipo  on asistencia_c(id_tipo_evento);

-- Detalle: un renglón por asistente. En Oracle NO tenía FK; acá se declaran todas.
create table asistencia_d (
  id_asistencia_d bigint generated by default as identity primary key,
  id_asistencia   bigint not null references asistencia_c(id_asistencia) on delete cascade,
  id_persona      bigint references personas(id_persona),
  id_han          bigint references han(id_han),
  id_division     varchar(10) references divisiones(codigo),
  id_distrito     bigint references distrito(id_distrito),
  id_estado       bigint references estados(id_estado),
  id_invitado_por bigint references personas(id_persona),
  tipo_situacion  smallint,
  observacion     varchar(200)
);
create index ix_asistencia_d_asist   on asistencia_d(id_asistencia);
create index ix_asistencia_d_persona on asistencia_d(id_persona);
create index ix_asistencia_d_han     on asistencia_d(id_han);

-- Unicidad recomendada (persona no repetida en el mismo evento).
-- OJO: los datos Oracle traen duplicados; hay que deduplicar ANTES de crear el índice.
-- Descomentar tras limpiar (ver script de migración de datos):
-- create unique index ux_asistencia_d_persona_evento
--   on asistencia_d(id_asistencia, id_persona) where id_persona is not null;

-- Tabla staging para importación masiva desde planillas (se conserva el patrón).
create table stg_asistencia_import (
  id             bigint generated by default as identity primary key,
  id_tipo_evento bigint,
  id_han         bigint,
  fecha          date,
  participante   varchar(100),
  division       varchar(10),
  id_estado      bigint,
  invitado_por   varchar(100),
  procesado      varchar(1),
  error_msg      varchar(4000),
  load_ts        timestamptz default now()
);

-- =============================================================================
-- 4. GRUPOS / ACTIVIDAD RELIGIOSA / SEGUIMIENTO
-- =============================================================================

create table grupos_personas (
  id_grupo_persona bigint generated by default as identity primary key,
  id_grupo         bigint references grupos(id_grupo),
  id_persona       bigint references personas(id_persona),
  id_cargo         bigint not null references cargo(id_cargo)
);

-- Shakubuku: quién introdujo a quién a la práctica (+ gohonzon / membresía).
create table shakubuku (
  id_shakubuku      bigint generated by default as identity primary key,
  id_shakubuku_de   bigint references personas(id_persona),
  id_shakubuku_para bigint references personas(id_persona),
  gohonzon          smallint default 0,
  membresia         smallint default 0,
  fecha_gohonzon    date,
  fecha_membresia   date,
  unique (id_shakubuku_de, id_shakubuku_para)
);

create table daimoku (
  id_daimoku bigint generated by default as identity primary key,
  id_persona bigint references personas(id_persona)
);

create table examen_personas (
  id_examen_personas bigint generated by default as identity primary key,
  id_examen          bigint references examenes(id_examen),
  id_persona         bigint references personas(id_persona)
);

create table suscripciones (
  id_suscripcion      bigint generated by default as identity primary key,
  id_persona          bigint references personas(id_persona),
  id_tipo_suscripcion bigint references tipo_suscripciones(id_tipo_suscripcion)
);

-- Metas por han / año.
create table objetivos (
  id_objetivo              bigint generated by default as identity primary key,
  mes                      smallint,
  anho                     smallint,
  id_han                   bigint references han(id_han),
  gohonzon                 integer,
  membresia                integer,
  nuevo_amigo              integer,
  porcentaje_participacion integer,
  suscripciones_sekyo      integer,
  revistas_sekyo           integer
);

-- =============================================================================
-- 5. SEGURIDAD (Supabase Auth + perfiles)
-- =============================================================================

create table perfiles (
  id         uuid primary key references auth.users(id) on delete cascade,
  id_persona bigint references personas(id_persona),
  id_rol     bigint references rol(id_rol),
  estado     smallint default 1,
  creado_en  timestamptz default now()
);

-- Helper: ¿el usuario actual puede editar? (RESPONSABLE=1 / ADMINISTRADOR=3)
create or replace function public.es_editor()
returns boolean
language sql stable security definer
set search_path = public
as $$
  select exists (
    select 1 from public.perfiles p
    where p.id = auth.uid() and p.id_rol in (1, 3)
  );
$$;

-- =============================================================================
-- 6. LÓGICA DE NEGOCIO (triggers portados de Oracle)
-- =============================================================================

create or replace function public.fn_asistencia_d_autofill()
returns trigger
language plpgsql
as $$
declare
  p_han      bigint;
  p_division varchar(10);
  p_estado   bigint;
begin
  if new.id_persona is null then
    return new;
  end if;

  select id_han, division, id_estado
    into p_han, p_division, p_estado
    from personas where id_persona = new.id_persona;

  new.id_han      := coalesce(new.id_han, p_han);
  new.id_division := coalesce(new.id_division, p_division);
  new.id_estado   := coalesce(new.id_estado, p_estado);

  if new.id_han is not null then
    select id_distrito into new.id_distrito from han where id_han = new.id_han;
  end if;

  if new.id_invitado_por is not null then
    insert into shakubuku (id_shakubuku_de, id_shakubuku_para, gohonzon, membresia)
    values (new.id_invitado_por, new.id_persona, 0, 0)
    on conflict (id_shakubuku_de, id_shakubuku_para) do nothing;
  end if;

  return new;
end;
$$;

create trigger trg_asistencia_d_autofill
  before insert or update on asistencia_d
  for each row execute function public.fn_asistencia_d_autofill();

create or replace function public.fn_shakubuku_gohonzon()
returns trigger
language plpgsql
as $$
begin
  if new.gohonzon = 1 and new.id_shakubuku_para is not null then
    update personas
       set titular_gohonzo = 1,
           fecha_ingreso = coalesce(
             fecha_ingreso,
             least(coalesce(new.fecha_gohonzon, new.fecha_membresia),
                   coalesce(new.fecha_membresia, new.fecha_gohonzon))
           )
     where id_persona = new.id_shakubuku_para;
  end if;
  return new;
end;
$$;

create trigger trg_shakubuku_gohonzon
  after insert or update on shakubuku
  for each row execute function public.fn_shakubuku_gohonzon();

create or replace function public.fn_touch_persona()
returns trigger language plpgsql as $$
begin
  new.fecha_actualizacion := now();
  return new;
end;
$$;

create trigger trg_touch_persona
  before update on personas
  for each row execute function public.fn_touch_persona();

-- =============================================================================
-- 7. VISTAS DE REPORTES
-- =============================================================================

create or replace view vw_estructura as
select h.id_han, h.nombre as han,
       d.id_distrito, d.nombre as distrito,
       c.id_cabildo, c.nombre as cabildo,
       r.id_region, r.nombre as region
from han h
left join distrito d on d.id_distrito = h.id_distrito
left join cabildo  c on c.id_cabildo  = d.id_cabildo
left join region   r on r.id_region   = c.id_region;

create or replace view vw_asistencia_detalle as
select ad.id_asistencia_d,
       ac.id_asistencia,
       ac.fecha_asistencia,
       te.nombre as tipo_evento,
       ad.id_persona,
       pe.nombre as persona,
       ad.id_division as division,
       e.descripcion as estado,
       est.han, est.distrito, est.cabildo, est.region,
       ad.id_invitado_por,
       inv.nombre as invitado_por
from asistencia_d ad
join asistencia_c ac on ac.id_asistencia = ad.id_asistencia
left join tipo_evento te on te.id_tipo_evento = ac.id_tipo_evento
left join personas pe on pe.id_persona = ad.id_persona
left join personas inv on inv.id_persona = ad.id_invitado_por
left join estados e on e.id_estado = ad.id_estado
left join vw_estructura est on est.id_han = ad.id_han;

create or replace view vw_asistencia_por_evento as
select ac.id_asistencia, ac.fecha_asistencia, te.nombre as tipo_evento,
       ac.id_han, h.nombre as han,
       count(ad.id_asistencia_d) as asistentes
from asistencia_c ac
left join asistencia_d ad on ad.id_asistencia = ac.id_asistencia
left join tipo_evento te on te.id_tipo_evento = ac.id_tipo_evento
left join han h on h.id_han = ac.id_han
group by ac.id_asistencia, ac.fecha_asistencia, te.nombre, ac.id_han, h.nombre;

create or replace view vw_participacion_miembro as
select pe.id_persona, pe.nombre, pe.division, h.nombre as han,
       count(ad.id_asistencia_d) as total_asistencias,
       max(ac.fecha_asistencia)  as ultima_asistencia
from personas pe
left join asistencia_d ad on ad.id_persona = pe.id_persona
left join asistencia_c ac on ac.id_asistencia = ad.id_asistencia
left join han h on h.id_han = pe.id_han
group by pe.id_persona, pe.nombre, pe.division, h.nombre;

-- =============================================================================
-- 8. ROW LEVEL SECURITY
-- =============================================================================
do $$
declare t text;
begin
  foreach t in array array[
    'region','cabildo','distrito','han','estados','divisiones','tipo_evento',
    'tipos_grupos','grupos','cargo','rol','examenes','tipo_suscripciones',
    'personas','asistencia_c','asistencia_d','stg_asistencia_import',
    'grupos_personas','shakubuku','daimoku','examen_personas','suscripciones',
    'objetivos','perfiles'
  ]
  loop
    execute format('alter table %I enable row level security;', t);
    execute format($f$
      create policy "sel_auth_%1$s" on %1$I
      for select to authenticated using (true);
    $f$, t);
    execute format($f$
      create policy "ins_edit_%1$s" on %1$I
      for insert to authenticated with check (public.es_editor());
    $f$, t);
    execute format($f$
      create policy "upd_edit_%1$s" on %1$I
      for update to authenticated using (public.es_editor()) with check (public.es_editor());
    $f$, t);
    execute format($f$
      create policy "del_edit_%1$s" on %1$I
      for delete to authenticated using (public.es_editor());
    $f$, t);
  end loop;
end $$;

create policy "sel_propio_perfil" on perfiles
  for select to authenticated using (id = auth.uid());

